  int kind = int(s2.x + 0.5);
  float streak = kind == 1 ? 0.0 : smoothstep(0.5, 0.85, csTN(vec2(uv.x * 2.2, uv.y * 0.1 + csTN(vec2(uv.x * 0.5, 7.0)) * 3.0)));
  col *= 1.0 - p_grime * streak * 0.45;
