  if (lookView > 0.5 && lookView < 1.5) col = mix(vec3(0.6), vec3(h1, h2, h3), sm);
  if (lookView > 1.5 && lookView < 2.5) col = vec3((S.h + p_pom) / p_pom);
  if (lookView > 3.5) col = csSolidColour(int(s2.w + 0.5) % 256);
