  p_warm = L1_warm;
  p_dark = L1_dark;
  p_mottle = L1_mottle;
  p_grime = L1_grime;
  p_damp = L1_damp;
  p_moss = L1_moss;
  p_rockContrast = L1_rockContrast;
  p_rockScale = L1_rockScale;
  p_mortScale = L1_mortScale;
  p_pom = L1_pom;
  p_pomOn = L1_pomOn;
  p_shadowOn = L1_shadowOn;
  p_stoneTint = L1_stoneTint;
  p_mortTint = L1_mortTint;
