  csRockLod = log2(max(fp / p_rockScale * 1024.0, 1.0));
  csMortLod = log2(max(fp / p_mortScale * 1024.0, 1.0));
  csFade = p_pomOn * (1.0 - smoothstep(0.006, 0.03, fp));
  uv = uv0;
  float zr = 0.0;
