      puv = uv; pz = zr;
      uv += duv; zr -= dz;
      S = csSample(uv);
    }
    if (zr <= S.h) {
      vec2 lo = puv, hi = uv;
      float zlo = pz, zhi = zr;
      for (int i = 0; i < 4; i++) {
        vec2 mu = 0.5 * (lo + hi);
        float mz = 0.5 * (zlo + zhi);
        CsS M = csSample(mu);
        if (mz <= M.h) { hi = mu; zhi = mz; S = M; } else { lo = mu; zlo = mz; }
      }
      uv = hi;
      zr = zhi;
    }
    S = csSample(uv);
