  float e = max(0.002, fp * 0.75);
  float hx = csSample(uv + vec2(e, 0.0)).h - S.h;
  float hy = csSample(uv + vec2(0.0, e)).h - S.h;
  vec3 rn = picDataLod(t_rockNrm, S.tuv, csRockLod).xyz * 2.0 - 1.0;
