  csFade = p_pomOn * (1.0 - smoothstep(0.006, 0.03, fp));
  uv = uv0;
  float zr = 0.0;
  CwS S = cwSample(uv);
  if (csFade > 0.0) {
    float vz = max(Vts.z, 0.1);
    int steps = int(mix(14.0, 4.0, clamp(Vts.z, 0.0, 1.0)));
    float dz = p_pom / float(steps);
    vec2 duv = -Vts.xy / vz * dz * csFade;
    vec2 puv = uv;
